from pathlib import Path
import hashlib,base64,zlib,json
p=Path("/app/leyenda_static")
assert hashlib.sha256((p/'index.html').read_bytes()).hexdigest()=='ab4b95daf58e31074fbcdca631031c4cfd704d392c8b1f02d42b335ebb8417a9', 'index.html'
assert hashlib.sha256((p/'ui.js').read_bytes()).hexdigest()=='66b4bfa1b521b185630527048442a0d01ba174edbd031c1be048f21389e266ab', 'ui.js'
files=json.loads(zlib.decompress(base64.b64decode('')))
for n,s in files.items():(p/n).write_text(s)
